SELECT 
    tran.ACCOUNT_NUMBER, cm.CUSTOMER_NUMBER , CM.CUS_SHORT_NAME,
    --cm.CUS_SHORT_NAME,
    --tran.currency,
        --SUM(CASE WHEN MONTH(tran.BOOKING_DATE) = 1 AND YEAR(tran.BOOKING_DATE) = 2024 THEN CONVERT(DECIMAL(20,2),tran.AMOUNT_LCY) ELSE 0 END) AS 'January_2024',
    --SUM(CASE WHEN MONTH(tran.BOOKING_DATE) = 2 AND YEAR(tran.BOOKING_DATE) = 2024 THEN CONVERT(DECIMAL(20,2),tran.AMOUNT_LCY) ELSE 0 END) AS 'February_2024',
    --SUM(CASE WHEN MONTH(tran.BOOKING_DATE) = 3 AND YEAR(tran.BOOKING_DATE) = 2024 THEN CONVERT(DECIMAL(20,2),tran.AMOUNT_LCY) ELSE 0 END) AS 'March_2024',
    --SUM(CASE WHEN MONTH(tran.BOOKING_DATE) = 4 AND YEAR(tran.BOOKING_DATE) = 2024 THEN CONVERT(DECIMAL(20,2),tran.AMOUNT_LCY) ELSE 0 END) AS 'April_2024',
    --SUM(CASE WHEN MONTH(tran.BOOKING_DATE) = 5 AND YEAR(tran.BOOKING_DATE) = 2024 THEN CONVERT(DECIMAL(20,2),tran.AMOUNT_LCY) ELSE 0 END) AS 'May_2024',
    --SUM(CASE WHEN MONTH(tran.BOOKING_DATE) = 6 AND YEAR(tran.BOOKING_DATE) = 2024 THEN CONVERT(DECIMAL(20,2),tran.AMOUNT_LCY) ELSE 0 END) AS 'June_2024',
    --SUM(CASE WHEN MONTH(tran.BOOKING_DATE) = 7 AND YEAR(tran.BOOKING_DATE) = 2024 THEN CONVERT(DECIMAL(20,2),tran.AMOUNT_LCY) ELSE 0 END) AS 'July_2024',
    --SUM(CASE WHEN MONTH(tran.BOOKING_DATE) = 8 AND YEAR(tran.BOOKING_DATE) = 2024 THEN CONVERT(DECIMAL(20,2),tran.AMOUNT_LCY) ELSE 0 END) AS 'August_2024',
    --SUM(CASE WHEN MONTH(tran.BOOKING_DATE) = 9 AND YEAR(tran.BOOKING_DATE) = 2024 THEN CONVERT(DECIMAL(20,2),tran.AMOUNT_LCY) ELSE 0 END) AS 'September_2024',
    --SUM(CASE WHEN MONTH(tran.BOOKING_DATE) = 10 AND YEAR(tran.BOOKING_DATE) = 2024 THEN CONVERT(DECIMAL(20,2),tran.AMOUNT_LCY) ELSE 0 END) AS 'October_2024',
    --SUM(CASE WHEN MONTH(tran.BOOKING_DATE) = 11 AND YEAR(tran.BOOKING_DATE) = 2024 THEN tran.AMOUNT_LCY ELSE 0 END) AS 'November_2024',
    --SUM(CASE WHEN MONTH(tran.BOOKING_DATE) = 12 AND YEAR(tran.BOOKING_DATE) = 2024 THEN tran.AMOUNT_LCY ELSE 0 END) AS 'December_2024',
    --SUM(CASE WHEN MONTH(tran.BOOKING_DATE) = 1 AND YEAR(tran.BOOKING_DATE) = 2025 THEN tran.AMOUNT_LCY ELSE 0 END) AS 'January_2025',
     --SUM(CASE WHEN MONTH(tran.BOOKING_DATE) = 2 AND YEAR(tran.BOOKING_DATE) = 2025 THEN tran.AMOUNT_LCY ELSE 0 END) AS 'February_2025',
      SUM(CASE WHEN MONTH(tran.BOOKING_DATE) = 3 AND YEAR(tran.BOOKING_DATE) = 2025 THEN tran.AMOUNT_LCY ELSE 0 END) AS 'March_2025'
FROM 
    dbcba.KE_ACCOUNT_TRANSACTIONS AS tran
    inner join dbcba.KE_Customer_Master cm
    on tran.CUSTOMER_ID = cm.CUSTOMER_NUMBER and cm.EXTRACTION_DATE = (select max(processing_date) from dbcba.end_of_day)
WHERE 
   tran.AMOUNT_LCY > 0 
    AND txn_code_initiation ='CUSTOMER' 
 and (tran.CREDIT_CUSTOMER <> tran.DEBIT_CUSTOMER 
     OR (tran.CREDIT_CUSTOMER IS NULL OR tran.CREDIT_CUSTOMER = '')
     OR (tran.DEBIT_CUSTOMER IS NULL OR tran.DEBIT_CUSTOMER = ''))
 and (tran.CUSTOMER_ID <> tran.DEBIT_CUSTOMER 
    OR (tran.CUSTOMER_ID IS NULL OR tran.CUSTOMER_ID = '')
    OR (tran.DEBIT_CUSTOMER IS NULL OR tran.DEBIT_CUSTOMER = ''))
      AND tran.TRANSACTION_CODE NOT IN ('1085', '766', '949', '945', '991', '941', '433', '1006', '85', 
   '234', '859', '940', '992', '947', '939', '946', '944', '948', '938', '1001')
    and tran.REVERSAL_MARKER<>'R'
